import{_ as s,o,c as t,ao as a}from"./chunks/framework.B0ggK6IF.js";const l=JSON.parse('{"title":"Pearson loss: design","description":"","frontmatter":{},"headers":[],"relativePath":"pearson-design.md","filePath":"pearson-design.md","lastUpdated":null}'),i={name:"pearson-design.md"};function n(d,e,r,c,p,h){return o(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="Pearson-loss:-design" tabindex="-1">Pearson loss: design <a class="header-anchor" href="#Pearson-loss:-design" aria-label="Permalink to &quot;Pearson loss: design {#Pearson-loss:-design}&quot;">​</a></h1><p>This page describes how <code>loss = :pearson</code> is defined and computed. For usage, see the <a href="./tutorials/pearson-loss">Pearson loss tutorial</a>.</p><p>Notation: for a group <code>g</code> with <code>n_g</code> rows <code>i</code>, weights <code>w_i</code>, total weight <code>W_g</code> and <code>a_i = w_i / W_g</code>; <code>p</code> the predictions and <code>p̄_g = sum_i a_i p_i</code>; <code>y</code> the target, standardised within the group as <code>ỹ_i = (y_i - ȳ_g) / s_g</code>, with <code>ȳ_g</code> and <code>s_g</code> its weighted mean and standard deviation.</p><h2 id="Objective" tabindex="-1">Objective <a class="header-anchor" href="#Objective" aria-label="Permalink to &quot;Objective {#Objective}&quot;">​</a></h2><p>The correlation itself is a poor Newton objective: its Hessian scales with the correlation, so it is near zero at low correlations. Instead, each group&#39;s centred prediction is fitted to its standardised target by weighted squared error, as in CatBoost&#39;s QueryRMSE:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>L = sum_g sum_i w_i (p_i - p̄_g - ỹ_i)^2</span></span>
<span class="line"><span>g_i = 2 w_i (p_i - p̄_g - ỹ_i)</span></span>
<span class="line"><span>h_i = 2 w_i</span></span></code></pre></div><p>The gradient is exact, since <code>sum_i w_i (p_i - p̄_g - ỹ_i) = 0</code> within each group. <code>h_i</code> is the exact diagonal without the centring term <code>-2 w_i^2 / W_g</code>, so it bounds the curvature from above.</p><p>With <code>s</code> the weighted standard deviation of <code>p</code> within the group and <code>r</code> its weighted correlation with <code>y</code>,</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sum_i a_i (p_i - p̄_g - ỹ_i)^2 = (s - r)^2 + 1 - r^2</span></span></code></pre></div><p>For a given direction of the predictions, a group&#39;s term is smallest at <code>s = r</code> when <code>r &gt; 0</code>, where it equals <code>1 - r^2</code>, so lowering the loss raises the correlation.</p><h2 id="Groups-and-weights" tabindex="-1">Groups and weights <a class="header-anchor" href="#Groups-and-weights" aria-label="Permalink to &quot;Groups and weights {#Groups-and-weights}&quot;">​</a></h2><p>Each group&#39;s term weighs by its total weight <code>W_g</code>, so with unit weights a group counts in proportion to its size. Weights <code>w_i = 1 / n_g</code> make every group count the same. A group with fewer than two rows or a constant target has <code>g_i = h_i = 0</code>, and fitting fails if no group is left.</p><p>A constant added to a group&#39;s predictions changes neither the loss nor the correlation, so no bias is fitted.</p>`,13)])])}const _=s(i,[["render",n]]);export{l as __pageData,_ as default};
